  'payment.shamNote':     { ar:'شام كاش يدعم 3 عملات — اختر العملة التي أرسلتها فعلياً', en:'Sham Cash supports 3 currencies — select the one you actually sent', tr:'Sham Cash 3 para birimini destekler — gerçekten gönderdiğinizi seçin', fr:'Sham Cash supporte 3 devises — choisissez celle envoyée', es:'Sham Cash admite 3 monedas — elige la que enviaste', pt:'Sham Cash suporta 3 moedas — escolha a que enviou', fa:'شام کاش از ۳ ارز پشتیبانی می‌کند — آنچه واقعاً ارسال کردید را انتخاب کنید', ru:'Sham Cash поддерживает 3 валюты — выберите ту, что отправили', de:'Sham Cash unterstützt 3 Währungen — wählen Sie die tatsächlich gesendete', id:'Sham Cash mendukung 3 mata uang — pilih yang benar-benar dikirim', ku:'شام کاش ٣ دراو پشتگیری دەکات — ئەوی کە واقیعاً نێردتت هەڵبژێرە' },
